import{_ as o,o as t,c as d,a2 as c}from"./chunks/framework.hwbV7reR.js";const _=JSON.parse('{"title":"Исходящий API и подключение узлов","description":"","frontmatter":{},"headers":[],"relativePath":"node-agent.md","filePath":"node-agent.md","lastUpdated":1791653181000}'),r={name:"node-agent.md"};function a(n,e,i,l,s,p){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="исходящии-api-и-подключение-узлов" tabindex="-1">Исходящий API и подключение узлов <a class="header-anchor" href="#исходящии-api-и-подключение-узлов" aria-label="Permalink to &quot;Исходящий API и подключение узлов&quot;">​</a></h1><p>Оркестратор вызывает HTTPS API собственного Undercore Amnezia-agent. SSH не входит в обработку клиентского запроса. У каждого узла свой служебный токен, HTTPS origin и стабильный <code>server_id</code>. Идентичность проверяется в ответе <code>connection</code> либо через health перед прежними операциями; успешного TCP-подключения недостаточно. Переадресации не выполняются.</p><table tabindex="0"><thead><tr><th>Запрос к агенту</th><th>Действие</th></tr></thead><tbody><tr><td><code>GET /v1/health</code></td><td>Проверить <code>status</code>, <code>server_id</code>, <code>protocol</code></td></tr><tr><td><code>GET /v1/clients</code></td><td>Получить занятость и сверить назначения</td></tr><tr><td><code>POST /v1/clients</code></td><td>Создать peer идемпотентно по <code>external_id</code></td></tr><tr><td><code>GET /v1/clients/{remote_id}</code></td><td>Проверить peer и срок</td></tr><tr><td><code>POST /v1/clients/{remote_id}/renew</code></td><td>Продлить срок с <code>idempotency_key</code></td></tr><tr><td><code>POST /v1/clients/{remote_id}/disable</code></td><td>Подтверждённо отозвать peer</td></tr><tr><td><code>POST /v1/clients/{remote_id}/enable</code></td><td>Включить peer в пределах срока</td></tr><tr><td><code>POST /v1/clients/{remote_id}/replace</code></td><td>Повторяемая замена по ожидаемой идентичности</td></tr><tr><td><code>GET /v1/clients/{remote_id}/connection</code></td><td>Атомарно сверить доступ и получить параметры за один reconcile</td></tr><tr><td><code>GET /v1/clients/{remote_id}/configuration</code></td><td>Получить документ AWG</td></tr><tr><td><code>GET /v1/clients/{remote_id}/amnezia</code></td><td>Получить legacy <code>vpn://</code> представление</td></tr></tbody></table><p>Создание передаёт <code>external_id</code> (ключ конкретного назначения), <code>device_id: account-v1</code> (совместимость агента), <code>name</code>, <code>expires_at</code> (UTC с миллисекундами). Этот <code>device_id</code> агента не равен каноническому идентификатору устройства во входящем API.</p><p>Драйвер проверяет идентификаторы ответа. Реальный <code>remote_id</code> хранится отдельно от стабильного <code>connection_id</code> оркестратора. Конфигурации возвращаются с <code>no-store</code>, не сохраняются в журнале оркестратора. Тела ошибок стороннего HTTP не передаются клиенту и не записываются в диагностические ответы.</p><h2 id="новыи-протокол" tabindex="-1">Новый протокол <a class="header-anchor" href="#новыи-протокол" aria-label="Permalink to &quot;Новый протокол&quot;">​</a></h2><p>Реализовать <code>NodeDriver</code>, зарегистрировать его в <code>DriverRegistry</code>, добавить тесты повторов, истечения срока и отзыва. Обязательны идемпотентное создание, исполнение срока на узле и подтверждённый отзыв. Затем включить capability в runtime и клиенте.</p><p>TrustTunnel должен возвращать собственный <code>trusttunnel-toml</code>, не имитировать AWG. Его экспериментальный драйвер пока не включён; <a href="./trusttunnel.html">статус и проект API</a>. Типизированный контейнер для параметров уже предусмотрен, но это не делает произвольный сторонний агент совместимым с сервисом.</p><h2 id="адреса" tabindex="-1">Адреса <a class="header-anchor" href="#адреса" aria-label="Permalink to &quot;Адреса&quot;">​</a></h2><p><code>api_url</code> — адрес управляющего API, не VPN endpoint и не адрес выхода в интернет. Входной адрес/порт туннеля отдаёт агент; выходной адрес задаёт маршрутизация/NAT самого VPN-узла. Смена DNS или <code>api_url</code> оркестратора сама по себе не меняет egress IP. Сохранение <code>server_id</code> при замене адреса допустимо только для того же логического узла с сохранёнными peer/journal. Новая пустая машина — новый узел.</p><h2 id="атомарная-выдача" tabindex="-1">Атомарная выдача <a class="header-anchor" href="#атомарная-выдача" aria-label="Permalink to &quot;Атомарная выдача&quot;">​</a></h2><p><code>NodeDriver.connection(node, remote_id, binding_key)</code> возвращает <code>NodeConnection</code>: состояние клиента и типизированный <code>TransportConfiguration</code>. Протокольный драйвер проверяет принадлежность до выдачи параметров; application дополнительно сверяет назначение, срок, capability, локальный запрет, lease и незавершённое переключение.</p><p>Amnezia-agent отвечает на <code>GET /v1/clients/{id}/connection</code> JSON-объектом: <code>schema_version: 1</code>, <code>status: ok</code>, <code>protocol: amneziawg</code>, <code>server_id</code>, <code>client</code> (прежний ClientView), <code>configuration</code> (секретный AWG-документ). HTTP/RPC выполняют одну сериализованную сверку с runtime. Неактивный/истёкший доступ возвращает 410, просроченный control lease — 503. При отсутствии настроенного server_id выдача запрещена. Ответ требует <code>Cache-Control: no-store</code>; весь JSON ограничен 4 MiB, документ внутри — 64 KiB. Ответ и ключи нигде не журналируются.</p><p>Только 404 либо 405 с <code>Allow: POST</code> переводит драйвер на прежнюю последовательность health/get/health/export. Второй вариант возникает у старого агента из-за общего POST-маршрута операций; прочие 405 не допускают fallback. Это позволяет поочерёдно обновлять узлы; неизвестный клиент остаётся 404 после проверки старым маршрутом. Ошибки авторизации, 409/410/503, неверная идентичность, схема или отсутствие no-store не вызывают downgrade. Проверка идёт на каждом запросе: отрицательный кэш возможностей узла и кэш секретных документов отсутствуют. Публичный контракт v2, ревизии и SQLite-схема не изменены.</p><h2 id="адаптеры-экспорта" tabindex="-1">Адаптеры экспорта <a class="header-anchor" href="#адаптеры-экспорта" aria-label="Permalink to &quot;Адаптеры экспорта&quot;">​</a></h2><p><code>NodeDriver.export(node, remote_id, format, qr_content_format)</code> возвращает <code>ExportDocument</code>; <code>DriverCapabilities.export_formats</code> перечисляет возможности. Адаптер выбирает исходный документ и валидирует его. Общий renderer на Segno строит PNG из уже выбранных байтов, не знает о серверах, аккаунтах и протоколах. <code>AmneziaExports</code> допускает conf/amnezia-vpn/qr; <code>WireGuardExports</code> — conf/qr. HTTP-слой не содержит ветвления по этим протоколам. Прежние v1-маршруты остаются для совместимости; новый backend использует v2 export. Агент и VPN runtime для этого обновления не меняются.</p><p>Версия 0.3.5 собирает <code>.vpn</code> в адаптере из выданного агентом <code>.conf</code>, включая параметры AWG 3.1. Старый <code>/amnezia</code> на узле больше не требуется. Парсер допускает один Interface/Peer и известные параметры, отклоняет неоднозначные/неизвестные поля, сохраняет native config и отдельные строковые поля <code>last_config</code>. Ключ клиента вычисляется стандартным X25519; исходные ключи не меняются. Формат сверён с <a href="https://github.com/amnezia-vpn/amnezia-client/tree/de93650a90739b87bb47a632872ea9d0adc9412f/client/core/models/protocols" target="_blank" rel="noreferrer">AmneziaVPN 5.0.3.0</a>. Неизвестные параметры нельзя молча отбрасывать для создания файла старой версии.</p><h2 id="короткие-разрешения-и-отказ-контроллера" tabindex="-1">Короткие разрешения и отказ контроллера <a class="header-anchor" href="#короткие-разрешения-и-отказ-контроллера" aria-label="Permalink to &quot;Короткие разрешения и отказ контроллера&quot;">​</a></h2><p>Узлы с lease_enabled должны подтверждать поддержку коротких разрешений и прекращать доступ после их истечения. Оркестратор периодически продлевает их отдельным worker. Длительная остановка контроллера поэтому может остановить VPN даже на исправном узле. При недоступности старого узла перенос ждёт безопасное истечение разрешения; обычный HTTP-таймаут не заменяет это ожидание. После включения leases откат допустим только на код, который продолжает исполнять этот контракт.</p><p>Для разработки другого протокола: <a href="./drivers.html">руководство по драйверам</a>.</p>',20)])])}const m=o(r,[["render",a]]);export{_ as __pageData,m as default};
